//! What every generated file shares: its header, and how two of them are compared.

/// Prefix of the checksum recorded beside the generated data.
pub const SOURCE_LINE: &str = "//! Map package SHA-256: ";

/// The opening lines of a generated file: what it holds, that it is generated, and its package checksum.
pub fn header(what: &str, source: &str) -> String {
    format!(
        "//! {what}\n//!\n//! Generated by `tools/import_map` (`cargo run --release --manifest-path \
         tools/import_map/Cargo.toml`):\n//! do not edit by hand; a correction belongs in the tool's \
         override list\n//! (`tools/import_map/src/overrides.rs`).\n{SOURCE_LINE}{source}.\n"
    )
}

/// Whether the committed and generated tables are identical.
pub fn same(one: &str, other: &str) -> bool {
    one.lines().eq(other.lines())
}

/// Read the checksum stored in the generated table's header.
pub fn source_of(text: &str) -> Option<&str> {
    text.lines()
        .find_map(|line| line.strip_prefix(SOURCE_LINE))
        .map(|source| source.trim_end_matches('.'))
}
